/bin/zsh -lc "python3 - <<'PY'
import json
import urllib.request
repos = {
    'unclebob/ub-mode': ['SKILL.md'],
    'DietrichGebert/ponytail': ['skills/ponytail/SKILL.md', 'skills/ponytail-review/SKILL.md'],
    'addyosmani/agent-skills': ['skills/constraint-driven-development/SKILL.md', 'skills/documentation-and-adrs/SKILL.md'],
}
for repo, paths in repos.items():
    try:
        req = urllib.request.Request(f'https://api.github.com/repos/{repo}/commits?per_page=1', headers={'User-Agent': 'local-project-guidance'})
        with urllib.request.urlopen(req, timeout=20) as response:
            revision = json.load(response)[0]['sha']
        print(f'REPOSITORY {repo} REVISION {revision}')
        for path in paths:
            try:
                with urllib.request.urlopen(f'https://raw.githubusercontent.com/{repo}/{revision}/{path}', timeout=20) as response:
                    content = response.read().decode()
                print(f'SOURCE https://github.com/{repo}/blob/{revision}/{path}\\n{content}\\n')
            except Exception as error:
                print(f'READ ERROR {path}: {error}')
    except Exception as error:
        print(f'REPOSITORY ERROR {repo}: {error}')
PY"

/bin/zsh -lc "node <<'NODE'
const { mkdtempSync, mkdirSync, copyFileSync, readFileSync, writeFileSync, symlinkSync, rmSync } = require('node:fs');
const { join, resolve } = require('node:path');
const { tmpdir } = require('node:os');
const { spawnSync } = require('node:child_process');
const project = process.cwd();
const temporary = mkdtempSync(join(tmpdir(), 'link-shelf-check-'));
const source = readFileSync('app.js', 'utf8');
try {
  mkdirSync(join(temporary, 'tests'));
  for (const file of ['package.json', 'index.html', 'style.css', 'tests/app.test.cjs']) {
    copyFileSync(resolve(project, file), join(temporary, file));
  }
  symlinkSync(resolve(project, 'node_modules'), join(temporary, 'node_modules'), 'dir');
  const mutations = [
    ['缺失 UTF-8 BOM', source.replace('FEFF', '0000'), /AssertionError/],
    ['未转义字段内引号', source.replace(/\\.replace\\(["'^'"\\n]*?\\)/, ''), /AssertionError/],
    ['错误地仅导出筛选分类', source.replace('bookmarksToCsv(bookmarks)', 'bookmarksToCsv(bookmarks.filter(item => "'!filter.value || item.category === filter.value))'"'), /AssertionError/],
    ['JavaScript 语法错误', source + '\\nconst = ;\\n', /SyntaxError/],
  ];
  for (const [name, mutated, expectedError] of mutations) {
    if (mutated === source) throw new Error('未成功构造校验样例：' + name);
    writeFileSync(join(temporary, 'app.js'), mutated);
    const check = spawnSync('npm', ['run', 'check'], { cwd: temporary, encoding: 'utf8' });
    if (check.error) throw check.error;
    const output = check.stdout + check.stderr;
    if (check.status === 0 || "'!expectedError.test(output)) throw new Error('"'校验样例结果不符：' + name + '\\n' + output);
    process.stdout.write('已确认检查会拒绝：' + name + '\\n');
  }
} finally {
  rmSync(temporary, { recursive: true, force: true });
}
NODE"
